(function installCh02ReverseBrakingFacade(global) {
  "use strict";

  const platform = global.ECTPPlatform = global.ECTPPlatform || {};
  platform.moduleFacades = platform.moduleFacades || {};
  platform.moduleData = platform.moduleData || {};

  const MODULE_ID = "ch02_reverse_braking";
  const ROUTE_ID = "reverse-braking";
  const GEOMETRY_LOCK_ID = "ch02_reverse_braking_reference_ui_locked_v2";
  const REFERENCE_IMAGE = "data:image/jpeg;base64,";
  const ns = (kind, id) => `${MODULE_ID}__${kind}__${id}`;
  const DEV = (id) => ns("dev", id);
  const PORT = (id) => ns("port", id);
  const WIRE = (id) => ns("wire", id);
  const EDGE = (id) => ns("edge", id);
  const CMP = (id) => ns("cmp", id);
  const clone = (value) => value === undefined ? undefined : JSON.parse(JSON.stringify(value));

  const circuitData = Object.freeze({
    schemaVersion: "1.0",
    moduleId: MODULE_ID,
    geometryLockId: GEOMETRY_LOCK_ID,
    reference: Object.freeze({ width: 943, height: 649, source: "user-reference-2026-08-30" }),
    ports: Object.freeze([
      { portId: PORT("l1"), x: 109, y: 66 }, { portId: PORT("l2"), x: 168, y: 66 }, { portId: PORT("l3"), x: 227, y: 66 },
      { portId: PORT("m_u"), x: 110, y: 569 }, { portId: PORT("m_v"), x: 168, y: 569 }, { portId: PORT("m_w"), x: 228, y: 569 },
      { portId: PORT("control_l_top"), x: 427, y: 108 }, { portId: PORT("control_r_top"), x: 921, y: 108 },
      { portId: PORT("control_l_bottom"), x: 427, y: 382 }, { portId: PORT("control_r_bottom"), x: 921, y: 382 }
    ]),
    junctions: Object.freeze([
      { junctionId: ns("junc", "run_branch"), x: 574, y: 211 },
      { junctionId: ns("junc", "brake_branch"), x: 574, y: 383 }
    ]),
    components: Object.freeze([
      { componentId: CMP("qf1"), deviceId: DEV("qf1"), type: "breaker", partType: "main_contact", label: "QF1", circuitDomain: "main", geometry: { x: 93, y: 66, width: 150, height: 95, orientation: 0 } },
      { componentId: CMP("fu1"), deviceId: DEV("fu1"), type: "fuse", partType: "fuse", label: "FU1", circuitDomain: "main", geometry: { x: 92, y: 167, width: 155, height: 60, orientation: 0 } },
      { componentId: CMP("km1_main"), deviceId: DEV("km1"), type: "contactor", partType: "main_contact", label: "KM1", circuitDomain: "main", geometry: { x: 92, y: 260, width: 155, height: 80, orientation: 0 } },
      { componentId: CMP("km2_main"), deviceId: DEV("km2"), type: "contactor", partType: "main_contact", label: "KM2", circuitDomain: "main", geometry: { x: 92, y: 354, width: 155, height: 85, orientation: 0 } },
      { componentId: CMP("fr_main"), deviceId: DEV("fr1"), type: "thermal_relay", partType: "thermal_element", label: "FR", circuitDomain: "main", geometry: { x: 93, y: 471, width: 150, height: 75, orientation: 0 } },
      { componentId: CMP("motor"), deviceId: DEV("m1"), type: "motor", partType: "load", label: "M", circuitDomain: "main", geometry: { x: 104, y: 548, width: 130, height: 98, orientation: 0 } },
      { componentId: CMP("sb1"), deviceId: DEV("sb1"), type: "push_button", partType: "no", label: "SB1", circuitDomain: "control", geometry: { x: 482, y: 176, width: 55, height: 54, orientation: 0 } },
      { componentId: CMP("sb2"), deviceId: DEV("sb2"), type: "push_button", partType: "nc", label: "SB2", circuitDomain: "control", geometry: { x: 614, y: 176, width: 55, height: 54, orientation: 0 } },
      { componentId: CMP("km1_hold"), deviceId: DEV("km1"), type: "contactor", partType: "aux_no", label: "KM1", circuitDomain: "control", geometry: { x: 610, y: 263, width: 65, height: 36, orientation: 0 } },
      { componentId: CMP("km2_interlock"), deviceId: DEV("km2"), type: "contactor", partType: "aux_nc", label: "KM2", circuitDomain: "control", geometry: { x: 731, y: 179, width: 52, height: 50, orientation: 0 } },
      { componentId: CMP("km1_coil"), deviceId: DEV("km1"), type: "contactor", partType: "coil", label: "KM1", circuitDomain: "control", geometry: { x: 824, y: 178, width: 48, height: 50, orientation: 0 } },
      { componentId: CMP("ks"), deviceId: DEV("ks"), type: "speed_relay", partType: "speed_no", label: "KS/KSF", circuitDomain: "control", geometry: { x: 480, y: 354, width: 55, height: 55, orientation: 0 } },
      { componentId: CMP("km1_interlock"), deviceId: DEV("km1"), type: "contactor", partType: "aux_nc", label: "KM1", circuitDomain: "control", geometry: { x: 608, y: 355, width: 65, height: 52, orientation: 0 } },
      { componentId: CMP("km2_coil"), deviceId: DEV("km2"), type: "contactor", partType: "coil", label: "KM2", circuitDomain: "control", geometry: { x: 725, y: 359, width: 47, height: 50, orientation: 0 } },
      { componentId: CMP("fr_nc"), deviceId: DEV("fr1"), type: "thermal_relay", partType: "protection_nc", label: "FR", circuitDomain: "control", geometry: { x: 824, y: 354, width: 54, height: 55, orientation: 0 } }
    ]),
    wires: Object.freeze([
      { wireId: WIRE("main_l1"), circuitDomain: "main", fromPort: PORT("l1"), toPort: PORT("m_u"), routePoints: [{x:109,y:66},{x:109,y:569}] },
      { wireId: WIRE("main_l2"), circuitDomain: "main", fromPort: PORT("l2"), toPort: PORT("m_v"), routePoints: [{x:168,y:66},{x:168,y:569}] },
      { wireId: WIRE("main_l3"), circuitDomain: "main", fromPort: PORT("l3"), toPort: PORT("m_w"), routePoints: [{x:227,y:66},{x:227,y:569}] },
      { wireId: WIRE("ctrl_run"), circuitDomain: "control", fromPort: PORT("control_l_top"), toPort: PORT("control_r_top"), routePoints: [{x:427,y:108},{x:921,y:108}] },
      { wireId: WIRE("ctrl_brake"), circuitDomain: "control", fromPort: PORT("control_l_bottom"), toPort: PORT("control_r_bottom"), routePoints: [{x:427,y:382},{x:921,y:382}] }
    ]),
    deviceEdges: Object.freeze([
      { edgeId: EDGE("qf1"), deviceId: DEV("qf1"), circuitDomain: "main", electricalRole: "contact", behavior: "QF" },
      { edgeId: EDGE("sb1_no"), deviceId: DEV("sb1"), circuitDomain: "control", electricalRole: "contact", behavior: "NO" },
      { edgeId: EDGE("sb2_nc"), deviceId: DEV("sb2"), circuitDomain: "control", electricalRole: "contact", behavior: "NC" },
      { edgeId: EDGE("km1_main"), deviceId: DEV("km1"), circuitDomain: "main", electricalRole: "contact", behavior: "NO" },
      { edgeId: EDGE("km1_hold"), deviceId: DEV("km1"), circuitDomain: "control", electricalRole: "contact", behavior: "NO" },
      { edgeId: EDGE("km1_interlock"), deviceId: DEV("km1"), circuitDomain: "control", electricalRole: "contact", behavior: "NC" },
      { edgeId: EDGE("km2_main"), deviceId: DEV("km2"), circuitDomain: "main", electricalRole: "contact", behavior: "NO" },
      { edgeId: EDGE("km2_interlock"), deviceId: DEV("km2"), circuitDomain: "control", electricalRole: "contact", behavior: "NC" },
      { edgeId: EDGE("ks_no"), deviceId: DEV("ks"), circuitDomain: "control", electricalRole: "contact", behavior: "NO" },
      { edgeId: EDGE("fr_nc"), deviceId: DEV("fr1"), circuitDomain: "control", electricalRole: "protection", behavior: "NC" }
    ])
  });
  platform.moduleData[MODULE_ID] = circuitData;

  function createReverseBrakingFacade(options = {}) {
    const context = options.context || {};
    const contracts = platform.contracts;
    if (!contracts) throw new Error(`${MODULE_ID} requires platform.contracts`);

    let mounted = false;
    let paused = false;
    let motionTimer = null;
    let model = null;

    function initialModel() {
      return {
        operationState: { qf1: "open", sb1: "released", sb2: "released", fr1: "normal" },
        stableControlState: { km1: false, km2: false, ks: false },
        motor: { rpm: 0, state: "stopped", direction: "none" },
        lastAction: { type: "RESET_MODULE", message: "等待操作。" },
        iterationCount: 0
      };
    }

    function clearTimer() {
      if (motionTimer === null) return;
      if (context.scope?.clearInterval) context.scope.clearInterval(motionTimer); else global.clearInterval(motionTimer);
      motionTimer = null;
    }
    function shellRender() { context.services?.renderShell?.(); }
    function setLast(type, message) { model.lastAction = { type, message }; }

    function stabilize() {
      const power = model.operationState.qf1 === "closed";
      const frNormal = model.operationState.fr1 === "normal";
      if (!power || !frNormal) { model.stableControlState.km1 = false; model.stableControlState.km2 = false; }
      if (model.stableControlState.km1) model.stableControlState.km2 = false;
      if (model.stableControlState.km2) model.stableControlState.km1 = false;
      model.stableControlState.ks = model.motor.rpm >= 160;
      if (model.motor.rpm <= 0) {
        model.motor.rpm = 0; model.motor.state = "stopped"; model.motor.direction = "none";
        model.stableControlState.ks = false; model.stableControlState.km2 = false;
      } else if (model.stableControlState.km2) {
        model.motor.state = "braking"; model.motor.direction = "forward";
      } else if (model.stableControlState.km1) {
        model.motor.state = "running"; model.motor.direction = "forward";
      } else {
        model.motor.state = "coasting"; model.motor.direction = "forward";
      }
      model.iterationCount += 1;
    }

    function startRamp() {
      clearTimer();
      const tick = () => {
        if (paused || model.operationState.qf1 !== "closed" || model.operationState.fr1 !== "normal" || !model.stableControlState.km1) { clearTimer(); return; }
        model.motor.rpm = Math.min(1450, model.motor.rpm + 145);
        stabilize(); render(); shellRender();
        if (model.motor.rpm >= 1450) clearTimer();
      };
      motionTimer = context.scope?.interval ? context.scope.interval(tick, 120) : global.setInterval(tick, 120);
    }

    function startBraking() {
      clearTimer();
      const tick = () => {
        if (paused || model.operationState.qf1 !== "closed" || model.operationState.fr1 !== "normal") { clearTimer(); return; }
        model.motor.rpm = Math.max(0, model.motor.rpm - 175);
        if (model.motor.rpm < 160) { model.stableControlState.ks = false; model.stableControlState.km2 = false; }
        stabilize();
        if (model.motor.rpm === 0) setLast("STOP_PRIMARY_PRESS", "转速降至零，KS 复位，KM2 自动断电，反接制动完成。");
        render(); shellRender();
        if (model.motor.rpm === 0) clearTimer();
      };
      motionTimer = context.scope?.interval ? context.scope.interval(tick, 110) : global.setInterval(tick, 110);
    }

    function getStateSnapshot() {
      return {
        schemaVersion: contracts.facadeSchemaVersion,
        moduleId: MODULE_ID,
        routeId: ROUTE_ID,
        operation: {
          power: model.operationState.qf1,
          controls: { start: model.operationState.sb1, stop: model.operationState.sb2 },
          protections: { overload: model.operationState.fr1 }
        },
        devices: {
          primaryContactor: { id: DEV("km1"), label: "KM1", energized: model.stableControlState.km1 },
          brakingContactor: { id: DEV("km2"), label: "KM2", energized: model.stableControlState.km2 },
          speedRelay: { id: DEV("ks"), label: "KS", energized: model.stableControlState.ks }
        },
        motor: { id: DEV("m1"), label: "M", state: model.motor.state, running: model.motor.rpm > 0, direction: model.motor.direction, rpm: Math.round(model.motor.rpm) }
      };
    }

    function normalizeSolverResult() {
      const s = getStateSnapshot();
      const power = s.operation.power === "closed";
      const frNormal = s.operation.protections.overload === "normal";
      const km1 = s.devices.primaryContactor.energized;
      const km2 = s.devices.brakingContactor.energized;
      const ks = s.devices.speedRelay.energized;
      return {
        ...contracts.createEmptySolverResult(MODULE_ID),
        stableDeviceStates: { [DEV("km1")]: km1, [DEV("km2")]: km2, [DEV("ks")]: ks },
        edgeStates: {
          [EDGE("qf1")]: { conductive: power }, [EDGE("sb1_no")]: { conductive: model.operationState.sb1 === "pressed" },
          [EDGE("sb2_nc")]: { conductive: model.operationState.sb2 !== "pressed" }, [EDGE("km1_main")]: { conductive: km1 },
          [EDGE("km1_hold")]: { conductive: km1 }, [EDGE("km1_interlock")]: { conductive: !km1 },
          [EDGE("km2_main")]: { conductive: km2 }, [EDGE("km2_interlock")]: { conductive: !km2 },
          [EDGE("ks_no")]: { conductive: ks }, [EDGE("fr_nc")]: { conductive: frNormal }
        },
        activeMainWireIds: power && (km1 || km2) ? [WIRE("main_l1"), WIRE("main_l2"), WIRE("main_l3")] : [],
        activeControlWireIds: power && frNormal ? [km2 ? WIRE("ctrl_brake") : WIRE("ctrl_run")] : [],
        partialWireIds: power && !frNormal ? [WIRE("ctrl_run")] : [],
        motorStates: { [DEV("m1")]: { running: s.motor.running, direction: s.motor.direction, state: s.motor.state, rpm: s.motor.rpm } },
        protectionStates: { [DEV("fr1")]: { state: model.operationState.fr1, tripped: !frNormal } },
        converged: true,
        iterationCount: model.iterationCount,
        lastAction: clone(model.lastAction),
        extension: { speedRelay: ks, braking: km2, rpm: s.motor.rpm }
      };
    }

    function getOperationViewModel() {
      const s = getStateSnapshot();
      const closed = s.operation.power === "closed";
      const overload = s.operation.protections.overload === "overload";
      return {
        schemaVersion: contracts.facadeSchemaVersion,
        moduleId: MODULE_ID,
        power: { deviceId: DEV("qf1"), closed, closeLabel: "QF 合闸", openLabel: "QF 分闸", closeEnabled: !closed, openEnabled: closed },
        controls: [
          { slot: "primary", visible: true, label: "SB 启动", stateText: s.devices.primaryContactor.energized ? "运行中" : "待命", buttonClass: "forward", action: "START_PRIMARY_PRESS" },
          { slot: "secondary", visible: true, label: "SB 停止", stateText: s.motor.rpm > 0 ? "可制动" : "已停止", buttonClass: "stop", action: "STOP_PRIMARY_PRESS" },
          { slot: "tertiary", visible: false }, { slot: "quaternary", visible: false }
        ],
        protection: { label: "FR 过载", resetLabel: "FR 复位", tripped: overload, toggleAction: "PROTECTION_TOGGLE", resetAction: "PROTECTION_RESET" },
        protections: [{ slot: "primary", visible: true, label: "FR 过载", resetLabel: "FR 复位", tripped: overload, toggleAction: "PROTECTION_TOGGLE", resetAction: "PROTECTION_RESET" }],
        actionStates: [
          { id: "qf", label: "QF", currentState: closed ? "closed" : "open", availableTransitions: [closed ? "open" : "close"], onAction: closed ? "POWER_OPEN" : "POWER_CLOSE", feedbackText: closed ? "QF 已合闸。" : "请先合闸 QF。" },
          { id: "start", label: "SB 启动", currentState: s.motor.state, availableTransitions: ["start"], onAction: "START_PRIMARY_PRESS", feedbackText: "SB1 启动 KM1，KM1 辅助常开触点形成自锁。" },
          { id: "stop", label: "SB 停止", currentState: s.motor.state, availableTransitions: ["brake"], onAction: "STOP_PRIMARY_PRESS", feedbackText: "停止后 KM1 释放，KS 在有转速时允许 KM2 投入反接制动。" },
          { id: "fr", label: "FR", currentState: overload ? "overload" : "normal", availableTransitions: [overload ? "reset" : "trip"], onAction: overload ? "PROTECTION_RESET" : "PROTECTION_TOGGLE", feedbackText: "FR 动作切断控制回路；复位不会自动启动。" }
        ]
      };
    }

    function getStatusViewModel() {
      const s = getStateSnapshot();
      const overload = s.operation.protections.overload === "overload";
      return {
        schemaVersion: contracts.facadeSchemaVersion,
        moduleId: MODULE_ID,
        rows: [
          { id: "qf", label: "QF", value: s.operation.power === "closed" ? "合闸" : "断开", tone: s.operation.power === "closed" ? "on" : "off" },
          { id: "ks", label: "KS", value: s.devices.speedRelay.energized ? "动作" : "未动作", tone: s.devices.speedRelay.energized ? "on" : "off" },
          { id: "km1", label: "KM1", value: s.devices.primaryContactor.energized ? "吸合" : "断电", tone: s.devices.primaryContactor.energized ? "forward" : "off" },
          { id: "fr", label: "FR", value: overload ? "过载" : "正常", tone: overload ? "error" : "on" },
          { id: "km2", label: "KM2", value: s.devices.brakingContactor.energized ? "吸合" : "断电", tone: s.devices.brakingContactor.energized ? "warning" : "off" },
          { id: "motor", label: "M", value: s.motor.state === "braking" ? `反接制动 ${s.motor.rpm} rpm` : s.motor.rpm > 0 ? `运行 ${s.motor.rpm} rpm` : "停止", tone: overload ? "error" : s.motor.state === "braking" ? "warning" : s.motor.rpm > 0 ? "forward" : "off" }
        ]
      };
    }

    function buildTeachingFeedback() {
      const s = getStateSnapshot();
      let text = "停止时按下 SB2，KM1 失电，线路切换；当电机反转连接转速降低并触发 KS 动作后，KM2 得电，电机反接制动，直至转速降为零，M 停止。";
      let title = "反接制动工作原理";
      if (s.operation.protections.overload === "overload") text = "FR 过载动作，控制回路断开，KM1、KM2 均失电，电机保护停止。";
      else if (s.devices.brakingContactor.energized) text = "SB2 已动作，KM1 释放；KS 检测到电机仍有转速，KM2 得电，主回路换相产生反向制动力矩，转速持续下降。";
      else if (s.devices.primaryContactor.energized) text = "SB1 启动后 KM1 得电并自锁，主触点闭合，电机正常运行；KS 随转速升高进入制动准备状态。";
      else if (s.operation.power === "closed") text = "QF 已合闸，控制电源接通，KM1、KM2 均未吸合，等待按下 SB1 启动。";
      return { title, text, steps: [], source: "solver" };
    }

    function buildReplaySteps() {
      return [
        { label: "QF 合闸", action: "POWER_CLOSE", payload: {} },
        { label: "SB 启动", action: "START_PRIMARY_PRESS", payload: {} },
        { label: "SB 停止", action: "STOP_PRIMARY_PRESS", payload: {} }
      ];
    }

    function applyAction(action) {
      switch (action.type) {
        case "POWER_CLOSE":
          model.operationState.qf1 = "closed"; setLast(action.type, "QF 已合闸，等待启动。"); break;
        case "POWER_OPEN":
          clearTimer(); model.operationState.qf1 = "open"; model.stableControlState.km1 = false; model.stableControlState.km2 = false; model.motor.rpm = 0; setLast(action.type, "QF 已分闸，电机停止。"); break;
        case "START_PRIMARY_PRESS":
          model.operationState.sb1 = "pressed";
          if (model.operationState.qf1 !== "closed") setLast(action.type, "请先合闸 QF。");
          else if (model.operationState.fr1 === "overload") setLast(action.type, "FR 已过载，请先复位。");
          else if (model.stableControlState.km2) setLast(action.type, "KM2 正在制动，KM1 被互锁。");
          else { model.stableControlState.km1 = true; model.stableControlState.km2 = false; setLast(action.type, "SB1 启动，KM1 得电并自锁，电机开始运行。"); startRamp(); }
          model.operationState.sb1 = "released"; break;
        case "STOP_PRIMARY_PRESS":
        case "STOP_PRESS":
          model.operationState.sb2 = "pressed"; model.stableControlState.km1 = false;
          if (model.motor.rpm >= 160 && model.operationState.qf1 === "closed" && model.operationState.fr1 === "normal") { model.stableControlState.ks = true; model.stableControlState.km2 = true; setLast(action.type, "SB2 停止：KM1 失电，KS 检测转速，KM2 投入反接制动。"); startBraking(); }
          else { model.stableControlState.km2 = false; model.motor.rpm = 0; setLast(action.type, "SB2 停止，电机已停止。"); }
          model.operationState.sb2 = "released"; break;
        case "PROTECTION_TOGGLE":
          clearTimer(); model.operationState.fr1 = model.operationState.fr1 === "normal" ? "overload" : "normal"; model.stableControlState.km1 = false; model.stableControlState.km2 = false; model.motor.rpm = 0; setLast(action.type, model.operationState.fr1 === "overload" ? "FR 过载动作，电机保护停止。" : "FR 恢复正常。"); break;
        case "PROTECTION_RESET":
          model.operationState.fr1 = "normal"; setLast(action.type, "FR 已复位，等待重新启动。"); break;
        case "RESET_MODULE":
          clearTimer(); model = initialModel(); break;
        default:
          throw new Error(`${MODULE_ID} does not support ${action.type}`);
      }
      stabilize();
    }

    function dispatchAction(actionInput) {
      const action = typeof actionInput === "string" ? contracts.createAction(actionInput) : actionInput;
      const report = contracts.validateAction(action);
      if (!report.valid) throw new Error(`Invalid ${MODULE_ID} action: ${report.errors.join("; ")}`);
      applyAction(action); render(); shellRender();
      return { action, state: getStateSnapshot(), solverResult: normalizeSolverResult(), operationViewModel: getOperationViewModel(), statusViewModel: getStatusViewModel(), feedback: buildTeachingFeedback() };
    }

    function overlaySvg(s) {
      const qf = s.operation.power === "closed";
      const km1 = s.devices.primaryContactor.energized;
      const km2 = s.devices.brakingContactor.energized;
      const ks = s.devices.speedRelay.energized;
      const overload = s.operation.protections.overload === "overload";
      const rpm = s.motor.rpm;
      const pieces = [];
      if (qf) {
        [109,168,227].forEach(x => pieces.push(`<line x1="${x-4}" y1="114" x2="${x-1}" y2="149" stroke="#17a35a" stroke-width="4" stroke-linecap="round" opacity=".92"/>`));
      }
      if (km1) {
        [110,168,228].forEach(x => pieces.push(`<line x1="${x-4}" y1="286" x2="${x-1}" y2="319" stroke="#176cff" stroke-width="4" stroke-linecap="round" opacity=".88"/>`));
        pieces.push(`<rect x="824" y="178" width="24" height="50" fill="rgba(23,108,255,.12)" stroke="#176cff" stroke-width="3"/>`);
      }
      if (km2) {
        [110,168,228].forEach(x => pieces.push(`<line x1="${x-4}" y1="380" x2="${x-1}" y2="414" stroke="#f08a24" stroke-width="4" stroke-linecap="round" opacity=".9"/>`));
        pieces.push(`<rect x="725" y="359" width="25" height="50" fill="rgba(240,138,36,.14)" stroke="#f08a24" stroke-width="3"/>`);
      }
      if (ks) pieces.push(`<circle cx="506" cy="371" r="14" fill="none" stroke="#15a05a" stroke-width="4" opacity=".9"/>`);
      if (overload) pieces.push(`<rect x="822" y="352" width="58" height="62" rx="8" fill="rgba(217,48,37,.08)" stroke="#d93025" stroke-width="3"/>`);
      if (rpm > 0) pieces.push(`<g class="rb-rotor"><circle cx="168" cy="604" r="24" fill="none" stroke="${km2 ? '#f08a24' : '#176cff'}" stroke-width="3" opacity=".78"/><line x1="144" y1="604" x2="192" y2="604" stroke="${km2 ? '#f08a24' : '#176cff'}" stroke-width="2"/></g>`);
      return pieces.join("");
    }

    function render() {
      if (!mounted || !context.mountRoot) return;
      const s = getStateSnapshot();
      context.mountRoot.innerHTML = `
        <div data-module="${MODULE_ID}" class="rb-ref-root">
          <style>
            [data-module="${MODULE_ID}"]{position:relative;width:100%;overflow:hidden;background:#fff;line-height:1}
            [data-module="${MODULE_ID}"] .rb-ref{display:block;width:100%;height:auto;user-select:none;-webkit-user-drag:none}
            [data-module="${MODULE_ID}"] .rb-layer{position:absolute;inset:0;width:100%;height:100%;pointer-events:none}
            [data-module="${MODULE_ID}"] .rb-hit{position:absolute;background:transparent;border:0;cursor:pointer;padding:0;border-radius:999px}
            [data-module="${MODULE_ID}"] .rb-hit:focus-visible{outline:3px solid #1677ff;outline-offset:2px}
            [data-module="${MODULE_ID}"] .rb-start{left:49.7%;top:24.5%;width:7.2%;height:10.2%}
            [data-module="${MODULE_ID}"] .rb-stop{left:63.6%;top:24.5%;width:7.2%;height:10.2%}
            [data-module="${MODULE_ID}"] .rb-start2{left:69.2%;top:78.1%;width:8.7%;height:16.0%}
            [data-module="${MODULE_ID}"] .rb-stop2{left:79.0%;top:78.1%;width:8.7%;height:16.0%}
            [data-module="${MODULE_ID}"] .rb-qf{left:8.5%;top:10%;width:18%;height:16%}
            [data-module="${MODULE_ID}"] .rb-rotor{transform-origin:168px 604px;animation:rb-spin 1.05s linear infinite}
            @keyframes rb-spin{to{transform:rotate(360deg)}}
            @media (prefers-reduced-motion:reduce){[data-module="${MODULE_ID}"] .rb-rotor{animation:none}}
          </style>
          <img class="rb-ref" src="${REFERENCE_IMAGE}" alt="反接制动控制主电路与控制电路" draggable="false"/>
          <svg class="rb-layer" viewBox="0 0 943 649" aria-hidden="true">${overlaySvg(s)}</svg>
          <button class="rb-hit rb-qf" type="button" data-rb-action="${s.operation.power === 'closed' ? 'POWER_OPEN' : 'POWER_CLOSE'}" aria-label="QF 合分闸"></button>
          <button class="rb-hit rb-start" type="button" data-rb-action="START_PRIMARY_PRESS" aria-label="SB1 启动"></button>
          <button class="rb-hit rb-stop" type="button" data-rb-action="STOP_PRIMARY_PRESS" aria-label="SB2 停止"></button>
          <button class="rb-hit rb-start2" type="button" data-rb-action="START_PRIMARY_PRESS" aria-label="启动"></button>
          <button class="rb-hit rb-stop2" type="button" data-rb-action="STOP_PRIMARY_PRESS" aria-label="停止"></button>
        </div>`;
      context.mountRoot.querySelectorAll("[data-rb-action]").forEach(btn => btn.addEventListener("click", () => dispatchAction(contracts.createAction(btn.getAttribute("data-rb-action"), {}, "module-canvas"))));
    }

    function validateGeometry() {
      const ids = new Set(), errors = [];
      [...circuitData.ports, ...circuitData.components, ...circuitData.wires, ...circuitData.deviceEdges].forEach(item => {
        const id = item.portId || item.componentId || item.wireId || item.edgeId;
        if (!id) errors.push("missing id"); else if (ids.has(id)) errors.push(`duplicate id: ${id}`); else ids.add(id);
      });
      return { valid: errors.length === 0, errors, geometryLockId: GEOMETRY_LOCK_ID };
    }

    function runTests() {
      const tests = [];
      const g = validateGeometry(); tests.push({name:"Geometry/ID 唯一",pass:g.valid});
      const t = initialModel(); t.operationState.qf1="closed"; t.stableControlState.km1=true; tests.push({name:"KM1 启动状态",pass:t.stableControlState.km1&&!t.stableControlState.km2});
      t.motor.rpm=1450; t.stableControlState.ks=true; t.stableControlState.km1=false; t.stableControlState.km2=true; tests.push({name:"KM2 反接制动互锁",pass:!t.stableControlState.km1&&t.stableControlState.km2});
      t.motor.rpm=0; t.stableControlState.ks=false; t.stableControlState.km2=false; tests.push({name:"零速切除 KM2",pass:!t.stableControlState.ks&&!t.stableControlState.km2});
      return { passed: tests.every(x=>x.pass), results: tests, geometry: g };
    }

    function reset() { clearTimer(); model = initialModel(); stabilize(); render(); shellRender(); return getStateSnapshot(); }
    model = initialModel(); stabilize();

    return Object.freeze({
      createInitialState: () => { model = initialModel(); stabilize(); return getStateSnapshot(); },
      getStateSnapshot,
      dispatchAction,
      solve: (message="reverse braking solve") => { setLast("SOLVE", String(message)); stabilize(); return normalizeSolverResult(); },
      normalizeSolverResult,
      getOperationViewModel,
      getStatusViewModel,
      buildTeachingFeedback,
      buildReplaySteps,
      mount: () => { mounted = true; paused = false; },
      render,
      reset,
      pause: () => { paused = true; clearTimer(); },
      resume: () => { paused = false; },
      unmount: () => { mounted = false; clearTimer(); if (context.mountRoot) context.mountRoot.replaceChildren(); },
      validateGeometry,
      runTests
    });
  }

  platform.moduleFacades.createReverseBrakingFacade = createReverseBrakingFacade;
})(globalThis);
